RECORD = {
    "id": "JAH-NMO2-000001",
    "name": "Chaltu",
    "kind": "first-name",
    "meaning": "Chaltu is a feminine given name in Oromo. Meaning: A classic Oromo girls' name.."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Cha")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

